 "content": "def transform(grid):
    """Copy the marked-color pattern to every matching all-zero location."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    markers = colors - {0}
    if len(markers) < 2:
        return [row[:] for row in grid]
    background = max(markers, key=lambda color: sum(v == color for row in grid for v in row))
    marker_colors = markers - {background}
    if len(marker_colors) != 1:
        return [row[:] for row in grid]
    marker = next(iter(marker_colors))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    rmin = min(r for r, c in points)
    cmin = min(c for r, c in points)
    pattern = [(r-rmin, c-cmin) for r, c in points]
    ph = max(r for r, c in pattern) + 1
    pw = max(c for r, c in pattern) + 1
    out = [row[:] for row in grid]
    for r0 in range(h-ph+1):
        for c0 in range(w-pw+1):
            cells = [(r0+dr, c0+dc) for dr, dc in pattern]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = marker
    return out
